import { styled, View } from '@tamagui/web';

import { useMessageContext } from './MessageContext';
import { ariaAndDataAttributes } from '../../helpers/ariaAndDataAttributes';
import { cx } from '../../helpers/composeClassNames';
import { pickWebPressHandlers } from '../../helpers/pickAttributes';
import type { DivRef } from '../../types/ElementAttributes';
import type { ItemPartAttributes } from '../Item/types';

export type MessageLeftContainerProps = ItemPartAttributes;

// generated by scripts/generate-frame-values.mts from @rocket.chat/fuselage-tokens, do not edit

const messageLeftFrame = {
	display: 'flex',
	flexDirection: 'column',
	alignItems: 'flex-end',
	flexShrink: 0,
	minWidth: 'auto',
	minHeight: 'auto',
	render: 'div',
	justifyContent: 'center',
	flexGrow: 0,
	flexBasis: 'auto',
	width: '2.25rem',
} as const;

const messageLeftLines = {
	two: {
		minHeight: 'calc(1.25rem + 1.25rem)',
	},
	one: {
		minHeight: '1.25rem',
	},
} as const;

// end of generated

// Declared where it renders: zero-runtime only erases a `styled()` whose every use is in its own module
const MessageLeftFrame = styled(View, {
	...messageLeftFrame,
	variants: { lines: messageLeftLines },
});

/**
 * The avatar column of a message. Inside a `Message` it spans the header and the first body line, or the first body line alone when the message is sequential.
 */
const MessageLeftContainer = (props: MessageLeftContainerProps) => {
	const message = useMessageContext();
	const lines = message && (message.sequential ? 'one' : 'two');

	return (
		<MessageLeftFrame
			lines={lines}
			className={cx('rcx-item__media', 'rcx-message-container--left', props.className)}
			render={
				<div
					{...ariaAndDataAttributes(props)}
					{...pickWebPressHandlers(props)}
					ref={props.ref as DivRef}
					id={props.id}
					title={props.title}
					role={props.role}
					tabIndex={props.tabIndex}
				/>
			}
		>
			{props.children}
		</MessageLeftFrame>
	);
};

export default MessageLeftContainer;
